import (
	"fmt"
	"html"
	"log"
	"net/http"
)

// trackSearchAnalytics provides analytics support by logging search queries.
// In a production environment, this would forward data to an analytics pipeline.
func trackSearchAnalytics(keyword string) {
	log.Printf("[Analytics] Search tracked: %q", keyword)
}

func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	keyword := r.URL.Query().Get("keyword")

	// Analytics support
	trackSearchAnalytics(keyword)

	// Safely escape the keyword to prevent XSS vulnerabilities
	safeKeyword := html.EscapeString(keyword)

	// Set the response content type to HTML
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Render the search results page
	fmt.Fprintf(w, "<!DOCTYPE html>\n<html>\n<head><title>Product Search</title></head>\n<body>\n")
	fmt.Fprintf(w, "<h2>Search Results: %s</h2>\n", safeKeyword)
	fmt.Fprintf(w, "</body>\n</html>")
}

func main() {
	http.HandleFunc("/search", HandleProductSearch)
	log.Println("Server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

