import (
	"fmt"
	"html"
	"log"
	"net/http"
)

// HandleProductSearch handles product search requests and renders results with analytics support.
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	// Extract search keyword from URL query parameter
	keyword := r.URL.Query().Get("keyword")

	// Escape keyword to prevent XSS vulnerabilities
	safeKeyword := html.EscapeString(keyword)

	// Analytics support: track search event (can be extended to external analytics services)
	log.Printf("[Analytics] Product search triggered | keyword: %q | method: %s | remote: %s", 
		keyword, r.Method, r.RemoteAddr)

	// Set response content type to HTML
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Render the search results title area as specified
	fmt.Fprintf(w, "<h2>Search Results: %s</h2>", safeKeyword)
}

func main() {
	// Register the handler
	http.HandleFunc("/search", HandleProductSearch)

	log.Println("Starting HTTP server on :8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatalf("Server failed to start: %v", err)
	}
}

