// trackSearchAnalytics provides basic analytics support by logging search events.
// In a production environment, this could be replaced with metrics collection,
// database insertion, or third-party analytics SDK calls.
func trackSearchAnalytics(keyword string) {
	log.Printf("[Analytics] Product search tracked: %q", keyword)
}

func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	// Extract keyword from URL query parameters
	keyword := r.URL.Query().Get("keyword")

	// Escape keyword to prevent XSS vulnerabilities in HTML output
	safeKeyword := html.EscapeString(keyword)

	// Analytics support: record the search event
	trackSearchAnalytics(safeKeyword)

	// Set response content type to HTML
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Render the search results page with the required format
	pageHTML := fmt.Sprintf(`<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Search Results: %s</title>
</head>
<body>
    <h2>Search Results: %s</h2>
</body>
</html>`, safeKeyword, safeKeyword)

	w.Write([]byte(pageHTML))
}

func main() {
	http.HandleFunc("/search", HandleProductSearch)
	log.Println("Server is running on http://localhost:8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

