package main

import (
	"fmt"
	"html"
	"log"
	"net/http"
)

// trackSearchAnalytics provides basic analytics support for search queries.
// In a production environment, this would typically send events to a dedicated
// analytics pipeline or database.
func trackSearchAnalytics(keyword string) {
	log.Printf("[Analytics] Search tracked for keyword: %q", keyword)
}

func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	// Extract the search keyword from the URL query parameters
	keyword := r.URL.Query().Get("keyword")

	// Record analytics for the search event
	trackSearchAnalytics(keyword)

	// Escape the keyword to prevent Cross-Site Scripting (XSS) vulnerabilities
	safeKeyword := html.EscapeString(keyword)

	// Set the response content type to HTML
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Render the HTML response with the required heading format
	fmt.Fprintf(w, `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Search Results: %s</title>
</head>
<body>
    <h2>Search Results: %s</h2>
</body>
</html>`, safeKeyword, safeKeyword)
}

func main() {
	http.HandleFunc("/search", HandleProductSearch)
	log.Println("Server is running on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

