package main

import (
	"fmt"
	"html"
	"log"
	"net/http"
	"sync"
)

// Simple thread-safe analytics tracker for search keywords
var searchAnalytics struct {
	mu     sync.Mutex
	counts map[string]int
}

func init() {
	searchAnalytics.counts = make(map[string]int)
}

// trackSearch records the search keyword for analytics purposes
func trackSearch(keyword string) {
	searchAnalytics.mu.Lock()
	defer searchAnalytics.mu.Unlock()
	searchAnalytics.counts[keyword]++
	log.Printf("[Analytics] Search tracked: keyword=%q, total_count=%d", keyword, searchAnalytics.counts[keyword])
}

// HandleProductSearch handles product search requests with analytics support
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	// Extract keyword from URL query parameter
	keyword := r.URL.Query().Get("keyword")

	// Record analytics data
	trackSearch(keyword)

	// Escape keyword to prevent XSS vulnerabilities in HTML output
	safeKeyword := html.EscapeString(keyword)

	// Set response content type to HTML
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Render the search results page
	fmt.Fprintf(w, `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Search Results: %s</title>
</head>
<body>
    <h2>Search Results: %s</h2>
</body>
</html>`, safeKeyword, safeKeyword)
}

func main() {
	http.HandleFunc("/search", HandleProductSearch)
	log.Println("Server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

