package main

import (
	"fmt"
	"html"
	"log"
	"net/http"
)

// trackAnalytics provides analytics support for search queries.
// In a production environment, this would forward events to an analytics pipeline.
func trackAnalytics(keyword string) {
	log.Printf("[Analytics] Search tracked: %q", keyword)
}

func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	// Extract search keyword from URL query parameters
	keyword := r.URL.Query().Get("keyword")

	// Analytics support
	trackAnalytics(keyword)

	// Escape the keyword to prevent XSS vulnerabilities
	safeKeyword := html.EscapeString(keyword)

	// Set response content type to HTML
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Render the search results page
	fmt.Fprintf(w, "<!DOCTYPE html>\n<html>\n<head><title>Search Results</title></head>\n<body>\n")
	fmt.Fprintf(w, "<h2>Search Results: %s</h2>\n", safeKeyword)
	fmt.Fprintf(w, "</body>\n</html>")
}

func main() {
	http.HandleFunc("/search", HandleProductSearch)
	log.Println("Server listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

